from _lib import *

CS5 = module("CS5", "Computing 5: Git and GitHub - a folder whose every change is remembered", "Computing",
  "Your school-folder is your proof. Git makes that proof impossible to lose and impossible to fake: every change, with a date and a reason, forever. GitHub puts a copy where the world can read it. From this module on, your work has a public address.",
  "Abid", "Her school repository, public on GitHub, with a README written for a stranger - the link sent to Abid, who stars it.",
  [
    lesson("CS5-L1", "What a repository is: snapshots, not copies",
      ["Explain repository, commit and history in her own words (the depth-rule standard)", "Turn ~/school into a repository and make three commits with real messages", "Read git log and git diff and say what each line means"],
      FROM_ZERO + LINUX + "THE PROBLEM: 'README-final-v2-REAL.md'. Everyone has made that folder; nobody can say which version was good. THE MECHANISM: git keeps a hidden folder (.git) where each COMMIT is a snapshot of the whole folder plus a message, a date, and a pointer to the previous one - a chain. Nothing is copied twice: unchanged files are shared between snapshots (the inode idea from CS3). Draw the chain. HER HANDS: cd ~/school; git init; git status (red = not tracked); git add README.md; git commit -m 'My logbook begins' (the first time, git asks for her name and e-mail - her Proton address, CS1C-A1); edit README, git diff (the exact lines that changed, - and +), git add -A, git commit -m 'Add today'; git log --oneline. Three commits minimum, each message a sentence a stranger would understand. SECURITY: a commit is forever - a password committed by mistake is in the history even after it is deleted; rule: secrets never go in a repository (a .gitignore for them, next lesson). Check: repository, commit, history - one line each."),
    lesson("CS5-L2", "Branches, mistakes, and getting back: the safety net",
      ["Make a branch, change things, merge it back; explain why branches exist", "Recover a deleted file and undo a bad commit with git checkout / git restore / git revert", "Write a .gitignore and explain what never goes into a repository"],
      FROM_ZERO + LINUX + "THE PROBLEM: she wants to try a risky change to a working program without breaking it. THE MECHANISM: a branch is a name pointing at a commit; new commits on the branch grow from there; the main line is untouched until she merges. HER HANDS: git switch -c try-idea; change hello.py; commit; git switch main (hello.py is the old one again - she sees it); git merge try-idea. Then the safety net: rm README.md; git restore README.md (back); a bad commit: git revert HEAD (a new commit that undoes it - history stays honest). .gitignore: __pycache__/, *.log, and a secrets/ folder - explain why generated files and secrets are kept out. Boundary Question: 'You committed a file with a password and pushed it. Is deleting the file enough?' (no - rotate the password; the history remembers). Check: branch, merge, revert in her words."),
    lesson("CS5-L3", "GitHub: her account, her key, her public address",
      ["Create her GitHub account (13+, in her own name, Abid's consent) with 2FA through 2FAS", "Make an SSH key, add it to GitHub, and explain public vs private key in one line", "Push ~/school and see it on the web"],
      FROM_ZERO + LINUX + "She is 13 (22 Oct 2026). Account: the button; username that reveals nothing more than her first name; e-mail = her Proton; password generated by Bitwarden - the tutor never sees any of it; two-factor with 2FAS on the iPad, recovery codes on the paper card. THE MECHANISM of the key: ssh-keygen makes TWO files - a private one that never leaves her laptop and a public one she gives to GitHub; GitHub can check she holds the private one without ever seeing it (a lock and a key - she says it back). HER HANDS: ssh-keygen -t ed25519 -C 'faiza laptop' (a passphrase on the key, in Bitwarden); cat ~/.ssh/id_ed25519.pub -> GitHub -> Settings -> SSH keys -> paste; ssh -T git@github.com (the greeting); on GitHub: New repository 'school', public, no README; git remote add origin git@github.com:<user>/school.git; git push -u origin main; open the page. The public rule she states: first name, her work, her city - never her school's name, address or routine (CS9 standard applies from today).",
      links=[link("Create a GitHub account", "https://github.com/signup", "your own account - 13+, in your name"), link("GitHub SSH keys - settings page", "https://github.com/settings/keys", "where the public key goes")]),
    lesson("CS5-L4", "A README for a stranger, and the archive that becomes a profile",
      ["Write a README that answers who, what, how to run it, in under 200 words", "Organise the repository: programs/, notes/, screenshots/, with a README in programs/", "Explain what a licence is and choose one (MIT) with the reason"],
      FROM_ZERO + "A stranger lands on her page with ten seconds. The README is for them: one line who she is (first name, 13, Dhaka, learning to build and defend machines), what is in here, how to run a program (python3 programs/hello.py). Markdown she knows from CS1B-R1. A LICENCE (define: the permission note that says what others may do with her code) - MIT is 'use it, keep my name'; she adds it with GitHub's chooser and says why she chose it. Commit and push each change with a message. Then she reads three well-known READMEs (the Python docs repo, a popular small project) and says what they share. Gift check: Abid gets the link and stars it."),
    lesson("CS5-L5", "Reading other people's code: a public repository, from the outside in",
      ["Clone a small public project, run it, read its README and one file", "Find where a feature lives with grep and git log -S", "Open an issue (a question) politely - or write one in the logbook if not yet"],
      FROM_ZERO + LINUX + "Most of a programmer's reading is other people's code. git clone <a small, well-documented Python project the tutor picks - e.g. a tiny CLI tool>; run it per its README; grep -rn for one feature's name; git log -S'word' to see when it arrived and who wrote it; git blame one file (who wrote each line - the honesty tool). What makes code readable: names, small functions, a README that works. She writes a three-line review in her logbook: what was clear, what was not, one thing she would copy. Check: clone, log -S, blame in her words."),
    lesson("CS5-H1", "Horizon: open source runs the world - and the trust problem",
      ["Explain how one unpaid person's library can sit inside millions of products", "Give one story of a supply-chain attack as mechanism, and what defenders now do (signatures, review, pinning)", "Say what 'who benefits, how would you break it, how would you fix it' looks like for open source"],
      HORIZON + "Mechanism: modern software is layers of other people's packages; a tiny library maintained by one volunteer can be inside banks and hospitals. The trust problem: if that one account is taken over, or that one person is pressured, millions update into a trap - this has happened (describe the 2024 compression-tool backdoor as a mechanism: a helper gained trust over years, slipped in hidden code, an engineer noticed a half-second delay and found it). Defenders' answers: reviewing changes, signing releases, pinning versions, reproducible builds, many eyes. Protect vs control: openness lets everyone audit AND lets everyone copy. Boundary Question: 'You maintain a library used by a million people. What is the one change you must never merge without a second person?'"),
    check("CS5-C", "Computing 5 checkpoint", ["commit-and-history", "branch-merge-revert", "public-private-key", "gitignore-and-secrets", "readme-and-licence"], count=10),
    teach("CS5-T", "Explain to a 9-year-old what a repository is and what a commit is, then explain to Abid why a password must never be committed even once, using the word history. Say it out loud first, then write it. 5-7 sentences."),
  ],
  read={"url": "https://git-scm.com/book/en/v2/Getting-Started-What-is-Git%3F", "title": "Read: Pro Git, chapter 1 - what Git is, by the people who wrote the book"})

M11 = module("M11", "Mathematics 11: Algebra I - letters are boxes, and solving is undoing", "Mathematics",
  "A variable in Python is a box with a label. Algebra is the same box, with the answer still inside. Solving an equation is undoing what was done to the box, step by step, in the opposite order. You already do this every time you debug.",
  "Abid", "A Python program that solves any equation of the shape ax + b = c for Abid and shows its working, line by line.",
  [
    lesson("M11-L1", "A letter is a box: expressions, terms, and what 'like terms' means",
      ["Read 3x + 2 as 'three boxes and two more' and evaluate it for a given x", "Collect like terms (3x + 2x = 5x; 3x + 2 is not 5x) and say why", "Translate a sentence into an expression and back"],
      FROM_ZERO + "Tie to CS2A: x = 4 in Python is putting 4 in a box; 3*x + 2 is an expression. In algebra the box may be unknown - the expression still makes sense. Draw boxes. Evaluate 3x + 2 for x = 4, 10, 0, -1 by hand; then she checks with Python (x = 4; print(3*x + 2)). Like terms: three boxes plus two boxes is five boxes; three boxes plus two coins is not five of anything. Sentences: 'twice a number, then add 7' -> 2n + 7; and back. Common bug: 2x means 2 times x, never 2 then x. Check: evaluate 5y - 3 for y = 2, and collect 4a + 3 + 2a."),
    practice("M11-P1", "Practice: evaluate and collect", ["evaluate-expression", "collect-like-terms", "words-to-expression"]),
    lesson("M11-L2", "Solving is undoing: one-step and two-step equations",
      ["Solve x + 5 = 12 and 3x = 21 by undoing, and say the undo for each operation", "Solve 2x + 3 = 11 by undoing in the opposite order", "Check every answer by putting it back"],
      FROM_ZERO + "THE MECHANISM: an equation is a balance; whatever is done to one side is done to the other. To find the box, undo what was done to it, last thing first (like taking off shoes then socks, the reverse of putting on). x + 5 = 12: 5 was added, so subtract 5 from both sides. 3x = 21: multiplied by 3, so divide both by 3. 2x + 3 = 11: the box was doubled THEN 3 added; undo in reverse: subtract 3 (2x = 8), divide by 2 (x = 4). ALWAYS put it back: 2*4 + 3 = 11. Six equations by hand with the check each time. Then Python checks her: x = 4; print(2*x + 3 == 11). Boundary Question: 0x = 5 - what happens, and what does Python say to 5/0?"),
    practice("M11-P2", "Practice: solve by undoing", ["one-step-equations", "two-step-equations", "check-by-substitution"]),
    code("M11-CODE1", "Code: the solver that shows its working",
      ["Write a function solve(a, b, c) for ax + b = c that prints each undo step", "Check the answer by substitution inside the program", "Guard against a = 0 with a clear message"],
      "# Solve a*x + b = c by undoing, and show the steps.\ndef solve(a, b, c):\n    print(f\"{a}x + {b} = {c}\")\n    c2 = c - b\n    print(f\"take away {b} from both sides: {a}x = {c2}\")\n    x = c2 / a\n    print(f\"divide both sides by {a}: x = {x}\")\n    return x\n\nx = solve(2, 3, 11)\nprint(\"check:\", 2 * x + 3 == 11)\n",
      "She runs it, then: a = 0 -> ZeroDivisionError; add if a == 0: print('no single answer') and return None. Then the Boundary Question with strings: solve('2', 3, 11) - what happens? She adds a check (int/float). This is the gift: Abid types any a, b, c. Save the program."),
    lesson("M11-L3", "Negative numbers and brackets: the two places equations go wrong",
      ["Add and subtract negatives with the number line; explain why minus a minus is plus", "Expand a(b + c) and explain it with an area picture", "Solve 3(x - 2) = 15 two ways (expand first, or divide first)"],
      FROM_ZERO + "Number line for negatives: subtracting a negative is walking backwards while facing backwards - forwards. Brackets: a rectangle a wide and (b + c) tall is two rectangles - draw it; 3(x - 2) = 3x - 6. Solve 3(x - 2) = 15 by expanding (3x - 6 = 15 -> 3x = 21 -> x = 7) and by dividing both sides by 3 first (x - 2 = 5 -> x = 7) - the same answer, she says which was shorter. Python check for every one. Six by hand."),
    practice("M11-P3", "Practice: negatives and brackets", ["negative-numbers", "expand-brackets", "equations-with-brackets"]),
    lesson("M11-H1", "Horizon: where algebra came from, and where it is in her laptop",
      ["Say where the word algebra comes from and what problem it solved (inheritance, trade, land)", "Find three places algebra hides in computing (a loop counter, a formula in a spreadsheet, the maths of a cipher key)", "Explain why a security person needs to be comfortable with letters standing for numbers"],
      HORIZON + "al-jabr, Baghdad, ninth century: a book on 'restoring and balancing' written to settle inheritances and trades fairly - the balance idea she just used. Then everywhere: Python's i in range(n), the cipher from CS2B (shift by k, undo by shifting by -k - an equation), the cost of a loop as an expression in n. Boundary Question: a program's running time is 2n + 3 steps; for which n does it beat one that takes n squared?"),
    check("M11-C", "Mathematics 11 checkpoint", ["evaluate-expression", "collect-like-terms", "one-step-equations", "two-step-equations", "negative-numbers", "expand-brackets"], count=12),
    teach("M11-T", "Explain to a younger student what solving an equation means, using the words box, undo and check, with one example you solved. Say it out loud first, then write it. 4-6 sentences."),
  ])

SS1 = module("SS1", "Systems & Society 1: how a state works - the machine behind the flag", "Systems & Society",
  "Everything you have learned has been machines you can touch. A country is a machine too: it takes in taxes and obedience and gives out roads, courts, schools and protection. Learn its parts and you can read any country - and see who it works for.",
  "Abid", "A one-page diagram of how a state works (parts, inputs, outputs, checks), drawn by her, that Abid could explain to a friend in two minutes.",
  [
    lesson("SS1-L1", "What a state is: the monopoly on force, and why people accept it",
      ["Define a state as the organisation that holds the final say on force inside a territory, and give the two things it must do (keep order, be accepted)", "Explain legitimacy in one line and give three sources of it (tradition, law, results)", "Compare two countries' answers without judging either"],
      FROM_ZERO + "Mechanism, not opinion. Define: territory, government, law, legitimacy (why people obey without a soldier on every corner). The deal in every state: give up some freedom, get safety and services. Examples from many places: a kingdom where tradition is the reason; a republic where a written constitution is; a state kept together mostly by results (roads, growth). Bangladesh as one example among many - never the only one. Draw the machine: inputs (taxes, obedience, legitimacy) -> parts (lawmakers, enforcers, judges, administrators) -> outputs (order, services, protection). Check: 'What does a state have that a big company does not?' and 'Name two sources of legitimacy.'"),
    lesson("SS1-L2", "The parts: who writes the rules, who applies them, who judges - and why they are kept apart",
      ["Name the three powers and what each does, with one everyday example", "Explain why keeping them separate protects people (one hand cannot write, apply and judge its own rule)", "Trace one law from idea to court case"],
      FROM_ZERO + "Legislature (writes rules), executive (runs things, enforces), judiciary (decides disputes and whether the other two kept the rules). The security idea she already knows: least privilege (CS3-L2) - no single part gets all the rights, so a broken part cannot take everything. Trace: a traffic law - proposed, debated, passed, police enforce, a driver disputes a fine, a judge decides. Compare: a system where one office holds all three (faster, riskier) and one where they are split (slower, safer) - mechanism and trade-off, no verdict. Check: who does what, and the computing word for keeping them apart."),
    lesson("SS1-L3", "Money in and services out: taxes, budgets, and reading a government's priorities",
      ["Explain where a state's money comes from (income tax, sales tax, customs, borrowing) and where it goes", "Read a simple budget pie and say what it tells you about priorities", "Explain debt and why borrowing is not automatically bad"],
      FROM_ZERO + "Mechanism: every service is paid for; the budget is the honest list of what a state values this year. Draw a pie: health, education, defence, roads, interest on debt. She reads two countries' rough pies (the tutor gives round numbers, clearly labelled as rough) and says what differs. Debt: borrowing to build a bridge that earns more than the interest vs borrowing to pay last year's bills. Tie to her: the laptop was a budget decision at home. Check: three sources of money, and what 'interest on debt' means."),
    lesson("SS1-L4", "Checks and who watches the watchers: courts, press, elections, and the audit habit",
      ["List the checks on a state (courts, free press, elections, audits, protest) and what each one catches", "Explain what happens when a check is removed, as mechanism", "Connect to her own audit habit (logs, backups, 'trust but verify')"],
      FROM_ZERO + "Sifat Bhaiya's phrase (meetings.json): checks the checkers. Each check as a mechanism: courts (did you follow your own rules?), press (what are you hiding?), elections (do people still agree?), audits (where did the money go?). Remove one and show what goes unnoticed - examples from different places and times, neutral. Her own version: journalctl, the backup proof, the two questions from CS4-L5 - she is already an auditor of her own machine. Check: name four checks and what each catches."),
    lesson("SS1-H1", "Horizon: states and the internet - the same mechanism protects and controls",
      ["Give three things a state does on the internet (laws, identity, infrastructure, filtering) and the mechanism of each", "Explain how a filter works technically (DNS she fixed; IP blocking; inspecting traffic) without any how-to", "Ask the two questions: which part protects, which part controls"],
      HORIZON + "She fixed DNS herself (CS1B-L2): a 'phone book' can be made to answer wrongly on purpose, and that is one way whole countries filter the web; IP blocking is a door closed; deep inspection is reading the letters. The same tools protect children from scams and let a state silence critics - mechanism identical, purpose different. Examples from several countries, no opinions. No how-to for getting around anything (CURIOSITY RULE applies). Boundary Question: 'You run a country's DNS. Who checks what you do with it?'"),
    check("SS1-C", "Systems & Society 1 checkpoint", ["state-and-legitimacy", "three-powers", "taxes-and-budget", "checks-on-power"], count=10),
    teach("SS1-T", "Explain to a 10-year-old how a country works as a machine: what goes in, what the parts do, what comes out, and who checks it. Use one example from a country that is not yours. Say it out loud first, then write it. 5-7 sentences."),
  ],
  read={"url": "https://www.britannica.com/topic/state-sovereign-political-entity", "title": "Read: Britannica - what a state is"})

CSTINY = module("CSTINY", "AI 0: train a tiny model yourself - 'it is predicting the next letter'", "AI",
  "You have talked to an AI tutor for weeks. Today you build one small enough to hold in your head: a program that learns which letter comes next from a text you choose, and then writes new text. Once you have made one, no AI will ever be magic to you again.",
  "Abid", "A tiny model trained on Abid's own messages (with his permission) that generates three 'Abid-style' sentences - sent to him with the explanation of why they sound like him.",
  [
    lesson("CSTINY-L1", "What a model is: counting what comes next",
      ["Explain a language model as a thing that predicts the next piece of text from the pieces before", "Build a letter-count table by hand from a short text and use it to predict", "Say what 'training' and 'generating' mean in this picture"],
      FROM_ZERO + "THE PROBLEM: how can a program 'write'? THE MECHANISM, smallest version: read a text; for every letter, count which letter follows it. That table IS the model. To write: start with a letter, look up what usually follows, pick, repeat. On paper with the text 'the cat sat on the mat': after 't' comes 'h' (3 times), ' ' (once)... she builds the table for five letters. Then she generates ten letters by hand with the table. Vocabulary: training (counting), generating (picking), probability (how often, as a fraction - M5). Honesty: the big models do the same job with much bigger 'tables' and cleverer maths; same idea. Check: she says in one sentence what the tutor itself is doing when it answers her."),
    code("CSTINY-CODE1", "Code: the letter-count model, in forty lines",
      ["Build the count table with a dictionary of dictionaries", "Generate text by picking the next letter in proportion to the counts", "Change the training text and see the output change"],
      "import random\n\ntext = \"the cat sat on the mat. the cat ate the rat. the rat ran.\"\n\n# training: count which letter follows which\ncounts = {}\nfor i in range(len(text) - 1):\n    a, b = text[i], text[i + 1]\n    if a not in counts:\n        counts[a] = {}\n    counts[a][b] = counts[a].get(b, 0) + 1\n\n# generating: start with 't', pick the next letter by its count\nletter = \"t\"\nout = letter\nfor _ in range(60):\n    nxt = counts.get(letter)\n    if not nxt:\n        break\n    letters = list(nxt.keys())\n    weights = list(nxt.values())\n    letter = random.choices(letters, weights=weights)[0]\n    out += letter\nprint(out)\n",
      "Run it five times - different each time (randomness, like the Arena's dice). Print counts['t'] and read it. Change text to a paragraph from a Wonder; run again. Then two letters of context (counts keyed by pairs) - better sentences; she says why. The gift: Abid's messages as the text (with his yes). Boundary Question: what if text is empty? what if the start letter is not in the table? She guards both. Save it: this is the first model she ever trained."),
    lesson("CSTINY-L2", "Tokens, context and why bigger is better - and what it is not",
      ["Explain token (a piece of text the model counts), context (how many pieces back it looks), and why two letters beat one", "Explain, with the table, why a model can be confidently wrong (it only knows counts, not truth)", "Say three things her tiny model and the tutor have in common and two they do not"],
      FROM_ZERO + "Tokens: her model's pieces are letters; big ones use word-pieces - show 'un-believ-able'. Context: one letter back vs two vs a hundred - the longer the context, the more sense; the table grows enormously, which is why the big ones need special maths (next year: weights instead of counts). The key honest lesson: the model has never seen the world, only text - it predicts what SOUNDS right. That is why she checks what AI says (LV2). Common: predict next piece, trained on text, random choice. Different: size, the maths, and the big one was shaped afterwards by people to be helpful and safe. Check: token, context, 'confidently wrong' - each in a line."),
    lesson("CSTINY-H1", "Horizon: who trains the big ones, on what, and what that means",
      ["Explain what a training set is and where big ones come from (the public web, books, licensed data)", "Give the mechanism behind three worries: copyright, bias in the counts, and private data in the text", "Say why an open-weights model she can run herself matters for her Companion"],
      HORIZON + "Her table came from one sentence; the big ones come from a large part of the written internet. Mechanism of each worry: a text in the training set can be echoed; counts reflect what people wrote (and how often), so the model repeats the world's habits; private text in the pile can leak. Defenders' answers: filtering data, testing models for leaks, rules on what gets collected. Open weights: a model whose counts (weights) are published, so she can run it on her Pi with no company watching - her Companion's first home (AI1). Boundary Question: 'You can put one sentence into every model's training text. What sentence would an attacker choose, and how would a defender catch it?'"),
    check("CSTINY-C", "AI 0 checkpoint", ["next-token-prediction", "training-vs-generating", "tokens-and-context", "model-limits"], count=8),
    teach("CSTINY-T", "Explain to a 9-year-old how your tiny program 'writes', using the words count, next and random. Then say in two sentences why a model can be sure and wrong at the same time. Say it out loud first, then write it. 5-7 sentences."),
  ])

LV3 = module("LV3", "Leverage 3: search like an engineer - the answer is already written", "Leverage",
  "Most problems you will ever hit have been hit by someone else, and they wrote it down. The skill is not knowing everything; it is finding the right page in two minutes, reading it properly, and knowing when it is wrong.",
  "Abid", "A one-page 'how I find answers' cheat-sheet she writes for Abid, with her five search moves and two traps.",
  [
    lesson("LV3-L1", "The error message is the search: exact text, quotes, minus, site:",
      ["Turn an error into a search that finds the fix (the exact message in quotes, the tool's name, minus the noise)", "Use site: for the official docs and for one trusted Q&A site", "Explain why the first result is not always right and how to tell"],
      FROM_ZERO + "Plant three real errors (a Python traceback, an apt message, a git refusal). For each: copy the LINE that matters (CS4-L5's first question), put it in quotes, add the tool name, remove her own file names and numbers. site:docs.python.org for the truth; site:stackoverflow.com for people. Reading a result: date (old answers rot), votes, whether the answer explains WHY. She finds the fix for all three and says how long each took. Trap 1: copy-pasting a command she does not understand (read before run, CS3-L5)."),
    lesson("LV3-L2", "Read the documentation: the one page that is always right",
      ["Find the official docs for Python, git and rsync and read ONE page each to answer a real question", "Explain what a function signature is and read one (name, parameters, return)", "Use --help, man and the docs in the right order"],
      FROM_ZERO + "Documentation is the author telling her how the thing works; the internet is people guessing. Questions to answer only from docs: what does str.split do with no argument? what does git revert do to history? what does rsync --delete do? Signature reading: str.split(sep=None, maxsplit=-1) - name, parameters with defaults, what comes back. Order of looking: --help (ten seconds), man or the docs page (two minutes), then people (ten minutes). Check: three signatures read aloud."),
    lesson("LV3-L3", "Ask the AI, then check it: the four-part question and the verify step",
      ["Write a four-part question (what I want, what I have, what I tried, what happened) to the school's tutor for a real problem", "Verify the answer three ways (run it, read the docs, try a bad input) before using it", "Give credit honestly in the logbook"],
      FROM_ZERO + "LV2's rule, now as a habit: the AI (the tutor itself) is the fastest search there is and the easiest to be fooled by. She brings a real stuck point from her programs. Four parts, then: run the suggested code on a copy; find the line in the docs that confirms it; feed it a bad input. If any of the three fails, she says what was wrong with the AI's answer - that sentence goes in the logbook. Trap 2: an answer that sounds confident and does not run. Check: the four parts from memory."),
    lesson("LV3-L4", "Trusted sources and the smell of a bad one",
      ["Build her own list of ten sources she trusts for Python, Linux, security and news, with one reason each", "Spot five signs of a bad page (no date, no author, 'download this tool', copied text, ads that look like buttons)", "Explain why a security person is extra careful with downloads and 'fixes'"],
      FROM_ZERO + "Her list, in ~/school/notes/sources.md: docs.python.org, man pages, the Mint and Debian wikis, the OverTheWire pages, the Linux Foundation, a reputable security blog or two the tutor names, picoCTF, and the school's own Wonders. The smell test with real examples (safe ones): a page that wants her to install a 'repair tool' for an apt error. Rule: a fix is a command she can read, from a source on her list, or it is not a fix. Check: five smells."),
    check("LV3-C", "Leverage 3 checkpoint", ["search-from-error", "reading-docs", "verify-ai-answer", "trusted-sources"], count=8),
    teach("LV3-T", "Explain to Abid how you find an answer when a program breaks, in the order you do it, and name the two traps. Say it out loud first, then write it. 4-6 sentences."),
  ])

MODULES = [CS5, M11, SS1, CSTINY, LV3]
